class CombineRepeatedJoinTests(TestCase):
    def test_or_repeated_self_m2m(self):
        parents = {name: Valid.objects.create(valid=name) for name in 'abcd'}
        matches = {}
        for name in ('ab', 'abcd', 'ac', 'acd', 'ad'):
            matches[name] = Valid.objects.create(valid=name)
            matches[name].parent.add(*(parents[letter] for letter in name))
        Valid.objects.create(valid='unrelated')

        lhs = Valid.objects.filter(parent__valid='a').filter(parent__valid='b')
        rhs = Valid.objects.filter(parent__valid='a').filter(parent__valid='c').exclude(parent__valid='d')
        # Dict iteration order must not cause equivalent joins to exchange
        # aliases when combining queries. The exclusion relabels a subquery.
        lhs.query.alias_map = OrderedDict(
            (alias, lhs.query.alias_map[alias]) for alias in reversed(lhs.query.tables)
        )
        rhs_sql = str(rhs.query)
        combined = lhs | rhs
        self.assertSequenceEqual(
            combined.distinct(), [matches['ab'], matches['abcd'], matches['ac']],
        )
        self.assertEqual(str(rhs.query), rhs_sql)


